import{_ as r,o as n,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const f=JSON.parse('{"title":"Wolfgang Hattmannsdorfer: Der neue Kronprinz der OÖVP","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/wolfgang-hattmannsdorfer.md","filePath":"recherche/wolfgang-hattmannsdorfer.md"}'),a={name:"recherche/wolfgang-hattmannsdorfer.md"};function s(o,e,d,l,g,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="wolfgang-hattmannsdorfer-der-neue-kronprinz-der-oovp" tabindex="-1">Wolfgang Hattmannsdorfer: Der neue Kronprinz der OÖVP <a class="header-anchor" href="#wolfgang-hattmannsdorfer-der-neue-kronprinz-der-oovp" aria-label="Permalink to &quot;Wolfgang Hattmannsdorfer: Der neue Kronprinz der OÖVP&quot;">​</a></h1><p>Mit dem Rückzug von August Wöginger am 23. März 2026 rückt eine Figur ins Rampenlicht, die bisher eher als strategischer Mastermind im Hintergrund agierte: <strong>Wolfgang Hattmannsdorfer</strong>. Er übernimmt nicht nur Wögingers Posten als stellvertretender Landesparteichef in Oberösterreich, sondern festigt damit auch seinen Anspruch auf die zukünftige Führung der Landespartei.</p><h2 id="wer-ist-wolfgang-hattmannsdorfer" tabindex="-1">Wer ist Wolfgang Hattmannsdorfer? <a class="header-anchor" href="#wer-ist-wolfgang-hattmannsdorfer" aria-label="Permalink to &quot;Wer ist Wolfgang Hattmannsdorfer?&quot;">​</a></h2><p>Hattmannsdorfer (*1979 in Linz) gilt als der „politische Vollprofi“ der oberösterreichischen Volkspartei. Seine Karriere ist geprägt von einem rasanten Aufstieg und einer konsequenten Vernetzung zwischen Landes- und Bundespolitik:</p><ol><li><strong>Der Stratege:</strong> Als Landesgeschäftsführer (2013–2021) war er der Architekt der Wahlerfolge von Landeshauptmann Thomas Stelzer. Er kennt die Strukturen der Macht in Oberösterreich wie kaum ein anderer.</li><li><strong>Der Hardliner:</strong> In seinen Rollen als Landesrat für Soziales und Integration sowie später auf Bundesebene positionierte er sich oft mit einer harten Linie – insbesondere bei Themen wie Sozialhilfe-Kürzungen und strengen Integrationsvorgaben.</li><li><strong>Der Netzwerker:</strong> Sein Wechsel als Generalsekretär in die Wirtschaftskammer (WKO) und später als Bundesminister für Wirtschaft in die Regierung Stocker zeigt seine tiefe Verwurzelung in den wirtschaftlichen Machtzentren des Landes.</li></ol><h2 id="die-rolle-im-„horten-mysterium" tabindex="-1">Die Rolle im „Horten-Mysterium“ <a class="header-anchor" href="#die-rolle-im-„horten-mysterium" aria-label="Permalink to &quot;Die Rolle im „Horten-Mysterium“&quot;">​</a></h2><p>Für unsere forensische Analyse ist Hattmannsdorfer ein Paradebeispiel für den <strong>„Pointillismus der Macht“</strong>. Während Wöginger die „Harte Prosa“ des direkten Postenschachers verkörperte, repräsentiert Hattmannsdorfer die moderne, strategische Form der politischen Einflussnahme:</p><ul><li><strong>Schachzug der Nachfolge:</strong> Die Nominierung zum Stellvertreter von Thomas Stelzer am 23. März wird intern als „Operation Kronprinz“ gewertet. Es ist der Versuch der OÖVP, sich vor dem Wöginger-Urteil am 21. April personell neu aufzustellen und den Fokus auf „Wirtschaftskompetenz“ und „Zukunft“ zu lenken.</li><li><strong>Vom Hintergrund ins Rampenlicht:</strong> Während Wöginger im Gerichtssaal in Linz um seine Reputation kämpft, baut Hattmannsdorfer seine Position als starkes Bindeglied zwischen Wien und Linz aus.</li></ul><h2 id="forensische-notiz" tabindex="-1">Forensische Notiz: <a class="header-anchor" href="#forensische-notiz" aria-label="Permalink to &quot;Forensische Notiz:&quot;">​</a></h2><p>Wir beobachten genau, wie Hattmannsdorfer das Erbe der Wöginger-Ära verwaltet. Wird er das System der „Harten Prosa“ fortführen oder in ein neues, glatteres Gewand hüllen? In <strong>Teil 4</strong> unseres Projekts wird er als Symbol für die „Marktbereinigung“ innerhalb der Partei eine zentrale Rolle spielen.</p><p>Die Zugriffe auf das Hattmannsdorfer-Profil in unserem Archiv sind seit heute Mittag sprunghaft angestiegen. Die Öffentlichkeit beginnt zu verstehen: <strong>Nach Wöginger kommt nicht das Vakuum, sondern die Strategie.</strong></p>',11)])])}const m=r(a,[["render",s]]);export{f as __pageData,m as default};
